    adcs_vec3_t n_b1, n_b2, n_r1, n_r2;
    adcs_vec3_t cb, ci;
    double nb, ni, db, di, theta_b, theta_i, diff;

    /* Check for null pointers */
    if ((b1 == NULL) || (b2 == NULL) || (r1 == NULL) || (r2 == NULL) || 
        (body_angle == NULL) || (inertial_angle == NULL) || (mismatch == NULL)) {
        return ADCS_E_NULL;
    }

    /* Normalize vectors */
    if (adcs_vec3_normalize(b1, ADCS_EPS_NORM, &n_b1) != ADCS_OK) return ADCS_E_DEGENERATE;
    if (adcs_vec3_normalize(b2, ADCS_EPS_NORM, &n_b2) != ADCS_OK) return ADCS_E_DEGENERATE;
    if (adcs_vec3_normalize(r1, ADCS_EPS_NORM, &n_r1) != ADCS_OK) return ADCS_E_DEGENERATE;
    if (adcs_vec3_normalize(r2, ADCS_EPS_NORM, &n_r2) != ADCS_OK) return ADCS_E_DEGENERATE;

    /* Compute cross products and their norms */
    cb = adcs_vec3_cross(&n_b1, &n_b2);
    ci = adcs_vec3_cross(&n_r1, &n_r2);

    nb = adcs_vec3_norm(&cb);
    ni = adcs_vec3_norm(&ci);

    /* Reject collinear pairs based on cross product norm threshold */
    if (nb <= ADCS_EPS_COLLINEAR) return ADCS_E_DEGENERATE;
    if (ni <= ADCS_EPS_COLLINEAR) return ADCS_E_DEGENERATE;

    /* Compute dot products */
    db = adcs_vec3_dot(&n_b1, &n_b2);
    di = adcs_vec3_dot(&n_r1, &n_r2);

    /* Calculate angles using atan2(norm(cross), dot) */
    theta_b = atan2(nb, db);
    theta_i = atan2(ni, di);

    /* Calculate mismatch as absolute difference */
    diff = fabs(theta_b - theta_i);

    /* Output results */
    *body_angle = theta_b;
    *inertial_angle = theta_i;
    *mismatch = diff;

    return ADCS_OK;
}

